def page(path,title,desc,body,og='home',schemas=None,home=False,noindex=False):
    assert len(title)<60,(title,len(title))
    assert len(desc)<155,(desc,len(desc))
    canonical=BASE+path
    data={'@context':'https://schema.org','@graph':[ORG,{'@type':'WebSite','@id':BASE+'/#website','name':'The Revenue Inbox','url':BASE+'/','publisher':{'@id':ORG['@id']}}]+(schemas or [])}
    head=f'''<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#161122"><meta property="og:type" content="{'article' if path.startswith('/case-studies/') else 'website'}"><meta property="og:site_name" content="The Revenue Inbox"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/og/{og}.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{e(title)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{BASE}/assets/og/{og}.png"><link rel="icon" href="/assets/brand/favicon.svg" type="image/svg+xml"><link rel="icon" href="/assets/brand/favicon-32.png" sizes="32x32"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><link rel="preload" href="/assets/font-6.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/font-0.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(data,ensure_ascii=False).replace('</','<\\/')}</script>'''
    content='<!doctype html><html lang="en"><head>'+head+'</head><body><a class="skip" href="#main">Skip to content</a>'+header()+'<main id="main">'+body+'</main>'+footer()+extras(home)+'<script src="/assets/vendor/gsap-3.13.0.min.js" defer></script><script src="/assets/vendor/ScrollTrigger-3.13.0.min.js" defer></script><script src="/script.js" defer></script></body></html>'
    target=ROOT/('index.html' if path=='/' else (path.strip('/')+'.html'))
    target.parent.mkdir(exist_ok=True,parents=True);target.write_text(content,encoding='utf8')
    return target

