def allocate(total,weights):
    raw=[total*x/sum(weights) for x in weights];out=[math.floor(x) for x in raw]
    for i in sorted(range(len(raw)),key=lambda i:raw[i]-out[i],reverse=True)[:total-sum(out)]:out[i]+=1
    return out
def series(rec):
    i=records.index(rec)
    if i==0:
        active=[int(d%7<5) for d in range(30)];sent=[(2500+(d%5)*75) if active[d] else 0 for d in range(30)]
        leads=allocate(26*sum(active),[active[d]*(22+(d%5)*2) for d in range(30)])
        return sent,leads,'Emails sent','Qualified leads',[(2650,'Emails sent'),(26,'Qualified leads'),(26,'Human calls')]
    if i==1:
        sent=allocate(221400,[(2000+5500*(d/89)**1.45) if d%7 in [0,1,3,4] else 0 for d in range(90)])
        return sent,allocate(159,sent),'Emails sent','Opportunities',[(221400,'Emails sent'),(3870,'Replies'),(159,'Qualified opportunities')]
    if i==2:
        days=allocate(47,[1 if d!=16 else 0 for d in range(30)]);days[16]=34
        return days,[], 'Meetings booked','',[(81,'Meetings booked')]
    if i==3:
        sent=allocate(45000,[(d+4)**1.3 if d%7<5 else 0 for d in range(21)])
        mt=allocate(12,[(d+1)**1.1 if d%7<5 else 0 for d in range(21)]);cum=[];v=0
        for k in mt:v+=k;cum.append(v)
        return sent,cum,'Emails sent','Meetings booked',[(45000,'Emails sent'),(504,'Replies, approximately'),(25,'Opportunities'),(12,'Qualified meetings')]
    if i==4:
        positive=allocate(470,[.6+d*.08 for d in range(12)]);capital=[];v=0
        for k in allocate(1200000,[max(0,d-2) for d in range(12)]):v+=k;capital.append(v)
        return positive,capital,'Positive replies','Cumulative capital',[(22451,'Investors contacted'),(470,'Positive replies'),(188,'Meetings booked'),(132,'Meetings held'),(18,'Investors closed')]
    daily=allocate(475,[12+d*.3+(d%7)*.3 for d in range(30)])
    return allocate(54600,[1]*30),daily,'Emails sent, approximately','Interested candidates',[(54600,'Emails sent, approximately'),(1340,'Replies, approximately'),(475,'Interested candidates')]

def chart(rec,mini=False):
    a,b,an,bn,funnel=series(rec);idx=records.index(rec);width=600;height=170 if mini else 230
    if idx==2:
        squares=''.join(f'<div class="heat-day {"record-day" if v==34 else ""}" style="--heat:{.15+.85*v/34}" title="{v} meetings"><span>{d+1}</span><b>{v}</b></div>' for d,v in enumerate(a))
        return f'<div class="calendar-heatmap" aria-label="Monthly distribution totaling 81 meetings, with a record day of 34">{squares}</div>'+('' if mini else '<p class="chart-note">81 meetings total <span>34 in one day · Company record</span></p>')
    maxa=max(a) or 1;maxb=max(b) if b else 1
    points=[(i*width/max(1,len(a)-1),height-20-v/maxa*(height-40)) for i,v in enumerate(a)]
    area=f'M0,{height} '+' '.join(f'L{x:.1f},{y:.1f}' for x,y in points)+f'L{width},{height}Z'
    line=' '.join(('M' if i==0 else 'L')+f'{i*width/max(1,len(b)-1):.1f},{height-20-v/maxb*(height-40):.1f}' for i,v in enumerate(b))
    bars=''
    if idx==4:
        bars=''.join(f'<rect class="chart-column" x="{i*50+8}" y="{height-20-v/maxa*(height-40):.1f}" width="30" height="{v/maxa*(height-40):.1f}" rx="3"/>' for i,v in enumerate(a))
    marker=''
    if idx==3:
        # User-approved correction: the current guarantee is 20; twelve has not passed it.
        maxb=20;line=' '.join(('M' if i==0 else 'L')+f'{i*width/20:.1f},{height-20-v/20*(height-40):.1f}' for i,v in enumerate(b))
        marker='<line class="guarantee-marker" x1="0" x2="600" y1="20" y2="20"/><text x="590" y="14" text-anchor="end">20 · 30-day guarantee</text>'
    marks=''
    if idx==5 and not mini:
        marks=''.join(f'<line class="optimization-marker" x1="{d/29*width}" x2="{d/29*width}" y1="20" y2="{height}"/>' for d in [6,13,20])
    return f'''<div class="volume-chart"><svg viewBox="0 0 600 {height}" role="img" aria-label="{e(an+' and '+bn)}"><title>{e(rec['name'])} campaign volume</title><desc>Reported campaign totals. Daily or weekly distribution is reconstructed from the supplied aggregate and ramp profile, not a dated transaction log.</desc><defs><linearGradient id="chart-fill-{rec['id']}{'-mini' if mini else ''}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8A40EA" stop-opacity=".3"/><stop offset="1" stop-color="#8A40EA" stop-opacity="0"/></linearGradient></defs><g class="chart-grid">{''.join(f'<line x1="0" x2="600" y1="{y}" y2="{y}"/>' for y in [40,100,160])}</g><g class="chart-draw">{bars or f'<path class="chart-area" d="{area}" fill="url(#chart-fill-{rec["id"]}{"-mini" if mini else ""})"/>'}{f'<path class="chart-line" d="{line}"/>' if line else ''}{marker}{marks}</g></svg></div>'''+('' if mini else f'<div class="chart-axis"><span>{"Week 1" if idx==4 else "Day 1"}</span><span>{"Week 12" if idx==4 else "Day "+str(len(a))}</span></div><div class="chart-legend"><span>{an}</span><span>{bn}</span></div>')

def dashboard(rec,mini=False):
    idx=records.index(rec);a,b,an,bn,funnel=series(rec)
    if mini:
        return f'<div class="mini-dashboard" data-ui aria-hidden="true"><div class="mini-top"><span>Campaign overview</span><i></i></div><div class="mini-metric"><b>{rec["primary"]}</b><span>{rec["metric"]}</span></div>{chart(rec,True)}</div>'
    running=idx in [0,3]
    kpis=''.join(f'<div class="kpi"><dt>{e(label)}</dt><dd data-final="{e(value)}">{e(value)}</dd></div>' for value,label in rec['kpis'])
    bars=''
    for i,(v,label) in enumerate(funnel):
        share=max(.035,math.sqrt(v/funnel[0][0]));rate='' if not i else f'{v/funnel[i-1][0]*100:.1f}% from prior stage'
        bars+=f'<div class="dash-funnel-row"><div><span>{e(label)}</span><b>{"~" if "approximately" in label else ""}{v:,}</b></div><div class="dash-track"><i style="--share:{share:.5f}"></i></div><small>{rate}</small></div>'
    if idx==2:bars+='<p class="micro">Positive reply count not supplied.<br>Attended: near-zero no-shows.</p>'
    if idx==0:bars+='<p class="micro">Daily funnel. Bar widths use a square-root scale so each reported stage remains visible.</p>'
    else:bars+='<p class="micro">Bar widths use a square-root scale. Counts and conversion rates are shown explicitly.</p>'
    feed=''.join(f'<li><span class="event-dot"></span><div><b>{"Human callback" if idx==0 else "Meeting booked" if idx in [2,3] else "Positive reply"}</b><span>{e(role)}</span></div><span class="feed-state">{icon("check")}</span></li>' for role in rec['feed'])
    tabs=''
    if idx==1:tabs='<div class="segment-tabs" role="group" aria-label="Activity by campaign vertical">'+''.join(f'<button type="button" data-segment="{label}" aria-pressed="false">{label}</button>' for label in ['Aviation','Hotels','Luxury resorts'])+'</div><p class="micro segment-note">All campaign totals. Select a vertical to view its activity.</p>'
    if idx==5:tabs='<div class="segment-tabs" role="group" aria-label="Address types"><span>Work email</span><span>Personal email</span></div>'
    return f'''<div class="dashboard" data-ui data-dashboard="{rec['id']}"><div class="dash-top"><div>{icon('mail')}<span>Campaign overview</span></div><span class="status-pill {'running' if running else ''}">{'Running' if running else 'Completed'}</span></div><div class="dash-window"><span>{e(rec['name'])}</span><span>Campaign window: {e(rec['period'])}</span></div><dl class="kpi-grid">{kpis}</dl><div class="dash-main"><div class="chart-panel"><div class="panel-title"><h3>{'Meeting calendar' if idx==2 else 'Campaign volume'}</h3><span>{e(rec['period'])}</span></div>{tabs}{chart(rec)}{chart_caption(rec)}{('<div class="peak-day">'+icon('calendar')+'<span>Peak day</span><b>18</b><span>investor meetings</span></div>') if idx==4 else ''}{'<p class="micro">Weekly optimization: days 7, 14 and 21.</p>' if idx==5 else ''}</div><div class="dash-funnel"><h3>{'Daily funnel' if idx==0 else 'Campaign funnel'}</h3>{bars}</div></div><div class="activity-feed"><div class="panel-title"><h3>Activity</h3><span>Representative events</span></div><div class="feed-viewport"><ul>{feed}</ul></div></div></div><p class="dashboard-proof">Totals pulled from the client's Instantly account. Dates shown are the campaign window.</p>'''

def chart_caption(rec):
    return '<p class="chart-source">Campaign totals are sourced. The '+('daily meeting distribution' if records.index(rec)==2 else 'daily or weekly profile')+' is reconstructed.</p>'

def case_card(rec):
    chips=''.join(f'<span class="stat-chip">{e(c)}</span>' for c in rec['chips'])
    return f'<article class="case-card" data-category="{rec["tag"]}"><a href="/case-studies/{rec["id"]}"><div class="case-card-top"><span>{e(rec["name"])}</span><span class="case-tag">{rec["tag"]}</span></div><h3>{e(rec["card"])}</h3>{dashboard(rec,True)}{chart_caption(rec)}<div class="case-card-bottom"><div class="stat-chips">{chips}</div><span class="card-arrow">{icon()}</span></div></a><div class="spotlight" aria-hidden="true"></div></article>'

def email_card(rec):
    fields={}
    notes=re.search(r'\*\*Merge field notes:\*\*(.*?)(?:\*\*Why it works|$)',rec['sections']['One email from the campaign'],re.S)
    if notes:
        for line in notes[1].strip().splitlines():
            if ':' in line:
                keys,definition=line.split(':',1)
                for key in re.findall(r'\{[^}]+\}',keys):fields[key]=definition.strip().rstrip('.')
    fields.setdefault('{signature}',"The client's sending signature")
    body=e(rec['email']);count=0
    def pill(match):
        nonlocal count
        key=html.unescape(match[0]);count+=1;desc=fields.get(key,"The prospect's verified contact data")
        return f'<button class="merge-pill" type="button" aria-label="{e(key+": "+desc)}" data-tooltip="{e(desc)}">{e(key)}</button>'
    body=re.sub(r'\{[^}]+\}',pill,body)
    why=re.search(r'\*\*Why it works \(one line under the card\):\*\* (.*)',rec['sections']['One email from the campaign'])
    return f'<div class="email-card" data-ui><div class="email-meta"><span>From: <i role="img" aria-label="Client sender"></i></span><span>To: {{firstname}}</span><span>Subject: First touch</span></div><div class="email-body">{body}</div></div><p class="email-caption">The first email in the sequence, as sent. Merge fields highlighted.</p>'+(f'<details class="field-notes"><summary>Merge field notes</summary>{md(notes[1].strip())}</details>' if notes else '')+(f'<p class="email-why">{e(why[1])}</p>' if why else '')

definitions=re.search(r'### 1.3 Definitions.*?\n(.*?)\n### 1.4',SOURCE,re.S)[1].strip()
for rec in records:
    parts=[]
    logo={0:'client-parking.webp',1:'client-skyhigh.svg',2:'client-0.webp',3:'client-grail.svg',4:'client-0.webp'}.get(records.index(rec))
    identity=f'<div class="case-identity"><img src="/assets/{logo}" alt="{e(rec["name"])}" width="170" height="64"></div>' if logo else '<p class="case-identity withheld">Client name withheld at their request.</p>'
    body=section('case-top',f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/case-studies">Case studies</a><span>/</span><span>{e(rec["name"])}</span></nav>{identity}<p class="eyebrow">{e(rec["eyebrow"])}</p><h1>{e(rec["h1"])}</h1><p class="case-subhead">{e(rec["sub"])}</p><div class="case-hero-action">{cta("case-hero","Book a strategy call")}<a class="text-link" href="#campaign-dashboard">Explore the campaign {icon()}</a></div>','case-hero')
    body+=section('campaign-dashboard','<h2 class="sr-only">Campaign dashboard</h2>'+dashboard(rec),'dashboard-section')
    snapshot=md(rec['sections']['Snapshot'])
    navlinks=''.join(f'<a href="#{re.sub("[^a-z]+","-",heading.lower()).strip("-")}">{e(heading)}</a>' for heading in rec['sections'] if heading not in ['H1','Subhead','KPI tiles','Snapshot','Quote slot','Built with','CTA headline','DASHBOARD DATA'])
    for heading,text in rec['sections'].items():
        if heading in ['H1','Subhead','KPI tiles','Snapshot','Quote slot','Built with','CTA headline','DASHBOARD DATA']:continue
        id=re.sub('[^a-z]+','-',heading.lower()).strip('-')
        if heading=='One email from the campaign':content=email_card(rec)
        else:
            if rec['id']=='graiai' and heading=='What it meant':text='Our standard promise is 20 qualified meetings in 30 days. GraiAI booked 12 in its first 21 days. And the campaign is still ramping.'
            content=md(text)
        parts.append(f'<section class="story-section" id="{id}"><h2>{e(heading)}</h2>{content}</section>')
    rec['rendered_story']=''.join(parts)
    body+=section('case-detail',f'<div class="case-reading-layout"><aside class="case-aside"><h2>Snapshot</h2>{snapshot}<details class="case-toc"><summary>In this campaign</summary><nav aria-label="On this page">{navlinks}</nav></details></aside><article class="case-story">'+''.join(parts)+f'<section class="story-section"><h2>Built with</h2><p>{e(rec["sections"]["Built with"])}</p></section><details class="definitions"><summary>How we count {icon("plus")}</summary><div>{md(definitions)}</div></details></article></div>')
    body+=closing(e(rec['sections']['CTA headline']),True)
