howdata=[('Get the buyer right.','You explain what you sell and who buys it. We own the strategy, ideal customer profile and prospect research.','You: explain the offer'),('Build the sending system.','We set up the domains, mailboxes, data and sending tools. You do not need to learn the infrastructure.','Us: build the system'),('Run the conversations.','We write the copy, run email and LinkedIn outreach, handle replies and follow up. You stay out of the inbox work.','Us: run the outbound'),('Show up and close.','We book qualified appointments. You take the sales calls and own the close.','You: take the calls')]
how=section('how-it-works',intro('Your offer.<br>Our job to get it heard.','From the first buyer list to the appointment on your calendar, the responsibility stays with us.')+'<ol class="how-grid">'+''.join(f'<li><span class="step-index">{i:02}</span><h3>{title}</h3><p>{sub}</p><span class="ownership">{owner}</span></li>' for i,(title,sub,owner) in enumerate(howdata,1))+'</ol><div class="section-action">'+cta('process')+'</div>','tonal-section')
roi=section('math',intro('Start with the deal<br>that pays for it.','Set your contract value and close rate. See the fees, the attended meetings and the number of closed deals needed to cover them.')+f'''<div class="roi-lab" data-ui><div class="roi-controls"><div class="control-block"><label for="contract-value">Average contract value <output id="contract-output" for="contract-value">$15,000</output></label><input type="range" id="contract-value" min="5000" max="100000" step="1000" value="15000" data-event="roi_toggle"><div class="preset-controls" role="group" aria-label="Contract value presets"><button type="button" data-contract="15000" aria-pressed="true">$15k</button><button type="button" data-contract="25000" aria-pressed="false">$25k</button><button type="button" data-contract="50000" aria-pressed="false">$50k</button></div></div><div class="control-block"><label for="close-rate">Close rate on attended meetings <output for="close-rate" id="close-output">10%</output></label><input type="range" id="close-rate" min="5" max="20" value="10" step="1" data-event="roi_toggle"><div class="range-labels"><span>5%</span><span>20%</span></div></div><p class="roi-caveat"><b>Revenue follows your sales cycle.</b> If you close in 60 days, revenue may arrive in month three or four. We assume an 80% show rate. These are scenarios, not promised results.</p><div class="break-even" aria-live="polite" aria-atomic="true"><span class="mono">Deals needed to break even</span><strong id="break-even">1</strong><p id="break-even-detail">$9,900 in conservative-scenario fees ÷ $15,000 per contract. One whole deal covers modeled fees, before delivery costs.</p></div></div><div class="roi-visual"><div class="panel-title"><h3>Your 90-day funnel</h3><span>Conservative scenario</span></div><div class="roi-funnel">'''+''.join(f'<div class="roi-stage"><div><span>{label}</span><b id="flow-{key}">{value}</b><small>{rate}</small></div><div class="roi-track"><i style="--flow:{flow}"></i>{"<span class=\"break-even-marker\" role=\"img\" aria-label=\"Break-even at one deal\"></span>" if key=="deals" else ""}</div></div>' for key,label,value,rate,flow in [('sent','Emails sent','60,000','90 days',1),('replies','Replies','600','1% of sent',.8),('positive','Positive replies','108','18% of replies',.62),('booked','Meetings booked','54','50% of positive',.46),('attended','Meetings attended','43','80% show rate',.32),('deals','Deals closed','4','10% close rate',.18)])+'''</div><p class="micro">Counts are explicit. Bar widths are visually compressed for readability.</p></div><div class="roi-scenarios"><div class="scenario"><span class="mono">Conservative</span><strong id="revenue-0">$60,000</strong><p><span id="deals-0">4</span> closed deals · <span id="fees-0">$9,900</span> fees</p></div><div class="scenario"><span class="mono">Expected</span><strong id="revenue-1">$105,000</strong><p><span id="deals-1">7</span> closed deals · <span id="fees-1">$13,600</span> fees</p></div><div class="scenario"><span class="mono">Strong</span><strong id="revenue-2">$150,000</strong><p><span id="deals-2">10</span> closed deals · <span id="fees-2">$18,000</span> fees</p></div></div><details class="model-assumptions"><summary>See every assumption '''+icon('plus')+'''</summary><p>60,000 emails in 90 days. Reply rates: 1%, 1.25%, 1.5%. Positive replies: 108, 165, 225. Booked meetings: 54, 91, 135. Attendance rounds down at 80%: 43, 72, 108. Deals round down at your chosen close rate. Fees: booked meetings × $100 + three months × $1,500. Contract revenue is before delivery costs, margin and tax. This model is not a prediction.</p></details></div><div class="section-action">'''+cta('roi')+'</div>')
