videos=section('testimonials',intro('The people behind the results.<br>On camera.','Watch the client interviews. Hear how the work changed their sales conversations.')+'<div class="video-grid">'+''.join(f'<article class="video-testimonial"><a class="video-facade" href="https://vimeo.com/{id}" data-video="{id}" data-event="video_play" aria-label="Play client interview: {e(caption)}"><img src="/assets/vimeo-{id}.webp" width="640" height="480" loading="lazy" alt="Client speaking in a Revenue Inbox video testimonial"><span class="video-gradient"></span><span class="video-quote">{e(caption)}</span><span class="play-control">{icon("play")}<span>Play client interview</span></span></a><p>{e(caption)}</p><span class="micro">Client testimonial</span></article>' for id,caption in vids)+'</div><div class="section-action">'+cta('video-proof')+'</div>')
pricing=section('pricing',intro('Pay for qualified appointments.<br>Know the full cost.')+f'''<div class="pricing-card"><div class="price-main"><p class="price-line"><strong>$100</strong><span>per booked appointment</span></p><p class="infrastructure-price">+ $1,500/month infrastructure</p><p class="price-terms">Domains, mailboxes, data and sending tools.<br>Rolling monthly. No long contract.</p><div class="price-example">At 20 booked appointments in a month: $2,000 + $1,500 = $3,500.</div><div class="price-slider"><label for="appointment-count">Appointments per month <output for="appointment-count" id="appointments-output">20</output></label><input id="appointment-count" type="range" min="10" max="60" value="20" step="1"><div class="price-calculation" aria-live="polite"><span>Monthly total <b id="monthly-total">$3,500</b></span><span>Effective cost per appointment <b id="effective-cost">$175</b></span></div></div>{cta('pricing')}</div><div class="price-inclusions"><h3>The whole job, included.</h3><ul>'''+''.join(f'<li>{icon("check")}<span>{x}</span></li>' for x in ['A buyer list built around who can actually buy.','Copy that gives those buyers a reason to reply.','Sending infrastructure managed on your behalf.','Email and LinkedIn outreach with replies handled.','Qualified appointments booked onto your calendar.'])+'</ul><a class="text-link" href="#guarantee">Read the guarantee '+icon()+'</a></div></div>','tonal-section')
guarantee=section('guarantee',f'<div class="guarantee-layout"><div class="guarantee-seal" aria-hidden="true">{icon("check")}</div><div><p class="eyebrow">Our commitment</p><h2>{PROMISE}</h2><p>Counted from the day campaigns go live. Qualified means a decision-maker inside your ICP who has agreed to hear your offer. We own strategy, data, copy, infrastructure, outreach and booking.</p>{cta("guarantee")}<p class="micro">Rolling monthly. No long contract.</p></div></div>','guarantee-section')
